function newGameFromPgn(pgn){const g=new Chess();if(pgn.trim())g.loadPgn(pgn);return g}
function readEditorBoard(fen){const board={};const rows=String(fen||'').split(' ')[0].split('/');rows.forEach((row,rowIndex)=>{let file=0;for(const cell of row){if(/\d/.test(cell)){file+=Number(cell);continue}const color=cell===cell.toUpperCase()?'w':'b',type=cell.toLowerCase();board[`${'abcdefgh'[file]}${8-rowIndex}`]={color,type};file++}});return board}
