function parseMoveText(text,startFen){const source=String(text||'').trim();if(!source)throw new Error('Enter some chess notation first.');if(!startFen||startFen===new Chess().fen()){try{const pgn=new Chess();pgn.loadPgn(source);if(pgn.history().length)return{game:pgn,moves:pgn.history({verbose:true}),startFen:new Chess().fen()}}catch{}}const game=new Chess(startFen||undefined);const tokens=source.replace(/\{[^}]*\}|\([^)]*\)|\$\d+/g,' ').replace(/\d+\.(\.\.)?/g,' ').split(/[\s,;]+/).filter(Boolean);for(const token of tokens){if(/^([a-h][1-8])[-x]?([a-h][1-8])([qrbn])?$/i.test(token)){const match=token.match(/^([a-h][1-8])[-x]?([a-h][1-8])([qrbn])?$/i);const move=game.move({from:match[1].toLowerCase(),to:match[2].toLowerCase(),promotion:match[3]?.toLowerCase()});if(!move)throw new Error(`Illegal move: ${token}`)}else{const move=game.move(token.replace(/[+#?!]+$/g,''));if(!move)throw new Error(`Could not read move: ${token}`)}}return{game,moves:game.history({verbose:true}),startFen:startFen||new Chess().fen()}}
function parsePositionText(text){const source=String(text||'').trim();if(!source)throw new Error('Enter a FEN or position notation.');if(source.includes('/'))return new Chess(source).fen();const game=new Chess();for(const rank of '12345678')for(const file of 'abcdefgh'){const square=file+rank;if(square!=='e1'&&square!=='e8')game.remove(square)}for(const raw of source.split(/[\s,;]+/).filter(Boolean)){const match=raw.match(/^(?:(w|b|white|black):)?([KQRBN])?([a-h][1-8])$/i);if(!match)throw new Error(`Could not read position piece: ${raw}`);const color=(match[1]||'w').toLowerCase().startsWith('b')?'b':'w',type=(match[2]||'P').toLowerCase(),square=match[3].toLowerCase();if(type==='k'){for(const file of 'abcdefgh'){for(const rank of '12345678'){const cell=file+rank,piece=game.get(cell);if(piece?.type==='k'&&piece.color===color)game.remove(cell)}}}game.remove(square);if(!game.put({type,color},square))throw new Error(`Could not place a piece on ${square}.`)}return game.fen()}
